const staticData = $getWorkflowStaticData("global");
if (!staticData.sessions) staticData.sessions = {};

const sessionId = $("Extract Input").first().json.sessionId;
const userMessage = $("Extract Input").first().json.userMessage;
const visitorEmail = $("Extract Input").first().json.visitorEmail;
const reply = $input.first().json.reply;

if (!staticData.sessions[sessionId]) {
  staticData.sessions[sessionId] = {
    email: visitorEmail,
    turns: []
  };
}

staticData.sessions[sessionId].turns.push({
  user: userMessage,
  assistant: reply,
  ts: Date.now()
});

const s = staticData.sessions[sessionId];
if (s.turns.length > 20) {
  s.turns = s.turns.slice(-20);
}

const cutoff = Date.now() - 86400000;
for (const sid of Object.keys(staticData.sessions)) {
  const sess = staticData.sessions[sid];
  if (sess.turns && sess.turns.length && sess.turns[sess.turns.length - 1].ts < cutoff) {
    delete staticData.sessions[sid];
  }
}

return $input.all();
